import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { StoreIntegrationRepository } from '@integration/repositories'
import type { ApplicationErrors } from '@integration/errors'
import { OrderOverride } from '../entities/OrderOverride'
import { OrderOverrideFieldsSchema } from '../objects/OrderOverrideFields'
import { OrderOverrideRepository } from '../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { OrderOverriddenEvent } from '../events'

export const UpdateOrderOverrideInputSchema = z.object({
	storeId: z.uuid(),
	orderIds: z.array(z.uuid()).min(1),
	patch: OrderOverrideFieldsSchema,
})

export const UpdateOrderOverrideOutputSchema = z.object({
	orderOverrideIds: z.array(z.uuid()),
})

/**
 * C26 UpdateOrderOverride (batch). The active `storeIntegrationExternalId`
 * is NOT part of the request — it is derived from the store's integration
 * (resolved from `storeId` via StoreIntegrationRepository). Upserts the
 * override pinned by `(orderId, storeIntegrationExternalId)` for every id
 * in `orderIds`:
 *   - if absent → create with the patch as initial fields
 *   - if present → merge the patch into existing fields (preserves
 *     non-supplied keys; spec rule "partial update on typed fields")
 *
 * No-op per-order: when the patch changes nothing for that id, the id
 * is still included in `orderOverrideIds` (the existing entity id) but
 * no event is emitted for it.
 *
 * Emits one OrderOverriddenEvent per changed order with the full entity
 * snapshot (SPEC-14). A separate handler in this BC republishes each as
 * the cross-BC `integration.shared.order.overridden` integration event.
 */
@injectable()
export class UpdateOrderOverride extends Handler<typeof UpdateOrderOverrideInputSchema, typeof UpdateOrderOverrideOutputSchema> {
	readonly name = 'update_order_override' as const
	readonly inputSchema = UpdateOrderOverrideInputSchema
	readonly outputSchema = UpdateOrderOverrideOutputSchema

	constructor(
		private readonly overrides: OrderOverrideRepository,
		private readonly storeIntegrations: StoreIntegrationRepository,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const storeIntegrationExternalId = await this.resolveExternalId(input.storeId, tx)

			const orderOverrideIds: string[] = []

			for (const orderId of input.orderIds) {
				const id = await this.applyOne(orderId, storeIntegrationExternalId, input, tx)
				orderOverrideIds.push(id)
			}

			return { orderOverrideIds }
		})
	}

	/**
	 * Derive the active `storeIntegrationExternalId` from the store's
	 * integration. The override pin speaks the provider's vocabulary
	 * (externalId), but the request only carries the storeId — so we
	 * resolve the store's integration here. A store with no integration
	 * cannot pin an override → STORE_INTEGRATION_NOT_FOUND.
	 */
	private async resolveExternalId(storeId: string, tx: Transaction): Promise<string> {
		const integrations = await this.storeIntegrations.findByStoreId(storeId, tx)
		const integration = integrations[0]
		if (!integration) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}
		return integration.externalId
	}

	private async applyOne(orderId: string, storeIntegrationExternalId: string, input: this['input'], tx: Transaction): Promise<string> {
		const existing = await this.overrides.findByPin(orderId, storeIntegrationExternalId, tx)

		let entity: OrderOverride

		if (existing) {
			const fieldsBefore = JSON.stringify(existing.fields)
			existing.mergeFields(input.patch)
			const fieldsAfter = JSON.stringify(existing.fields)
			// No-op: patch changed nothing — skip save and event emission.
			if (fieldsBefore === fieldsAfter) {
				return existing.id.value
			}
			entity = existing
		} else {
			entity = OrderOverride.create({
				storeId: input.storeId,
				orderId,
				storeIntegrationExternalId,
				fields: input.patch,
			})
		}

		await this.overrides.save(entity, tx)

		await this.domainEventRepository.save(
			new OrderOverriddenEvent({
				entityId: entity.id.value,
				ownerId: entity.storeId.value,
				payload: {
					orderId: entity.orderId.value,
					storeId: entity.storeId.value,
					storeIntegrationExternalId: entity.storeIntegrationExternalId,
					entity: {
						orderId: entity.orderId.value,
						storeId: entity.storeId.value,
						storeIntegrationExternalId: entity.storeIntegrationExternalId,
						fields: entity.fields,
					},
				},
			}),
			tx,
		)

		return entity.id.value
	}
}

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { OrderOverrideFieldsSchema, type OrderOverrideFieldsInput } from '../objects/OrderOverrideFields'
import type { SalesDomainErrors } from '../errors'

export const OrderOverrideSchema = z.object({
	storeId: z.instance(Id),
	orderId: z.instance(Id),
	storeIntegrationExternalId: z.string(),
	fields: OrderOverrideFieldsSchema,
})

export type OrderOverrideProps = Z.infer<typeof OrderOverrideSchema>

/**
 * Deterministic id for an OrderOverride. The natural key is
 * (orderId, storeIntegrationExternalId) — the same pair that pins the
 * row in `order_overrides`. Deriving the entity id from that key keeps
 * id stable across read-rehydrate cycles even when the table doesn't
 * carry a surrogate UUID column.
 */
export function orderOverrideId(orderId: string, storeIntegrationExternalId: string): string {
	return Id.fromSeed('order_override', orderId, storeIntegrationExternalId).value
}

export class OrderOverride extends AggregateRoot<typeof OrderOverrideSchema> {
	static override schema = OrderOverrideSchema

	static create(data: {
		storeId: string
		orderId: string
		storeIntegrationExternalId: string
		fields: OrderOverrideFieldsInput
	}): OrderOverride {
		const parsed = OrderOverrideFieldsSchema.safeParse(data.fields)
		if (!parsed.success) {
			throw new BaseError<SalesDomainErrors>('INVALID_ORDER_OVERRIDE_FIELDS', parsed.error.issues[0]?.message ?? 'Invalid override fields')
		}
		return new OrderOverride({
			id: orderOverrideId(data.orderId, data.storeIntegrationExternalId),
			...data,
			fields: parsed.data,
		})
	}

	mergeFields(patch: OrderOverrideFieldsInput): void {
		const parsed = OrderOverrideFieldsSchema.safeParse(patch)
		if (!parsed.success) {
			throw new BaseError<SalesDomainErrors>('INVALID_ORDER_OVERRIDE_FIELDS', parsed.error.issues[0]?.message ?? 'Invalid override fields')
		}
		this.fields = { ...this.fields, ...parsed.data }
	}

	/** Replace the resolved per-line product cost (SPEC-11 ProductCostApplicationHandler output). */
	setProductCostByLine(byLine: NonNullable<OrderOverrideFieldsInput['productCostByLine']>): void {
		const next = { ...this.fields, productCostByLine: byLine }
		const parsed = OrderOverrideFieldsSchema.safeParse(next)
		if (!parsed.success) {
			throw new BaseError<SalesDomainErrors>('INVALID_ORDER_OVERRIDE_FIELDS', parsed.error.issues[0]?.message ?? 'Invalid override fields')
		}
		this.fields = parsed.data
	}
}

export interface OrderOverride extends OrderOverrideProps {}

import { injectable } from 'tsyringe-neo'
import type { Transaction } from '@bk-dash/core-typescript'
import { OrderOverride } from '../../entities/OrderOverride'
import { OrderOverrideRepository } from './OrderOverrideRepository'

@injectable()
export class MockOrderOverrideRepository extends OrderOverrideRepository {
	private store = new Map<string, OrderOverride>()

	private key(orderId: string, storeIntegrationExternalId: string): string {
		return `${orderId}:${storeIntegrationExternalId}`
	}

	async findByPin(orderId: string, storeIntegrationExternalId: string, _tx?: Transaction): Promise<OrderOverride | undefined> {
		return this.store.get(this.key(orderId, storeIntegrationExternalId))
	}

	async save(entity: OrderOverride, _tx?: Transaction): Promise<OrderOverride> {
		entity.incrementVersion()
		this.store.set(this.key(entity.orderId.value, entity.storeIntegrationExternalId), entity)
		return entity
	}

	async delete(_id: string, _tx?: Transaction): Promise<void> {
		for (const [k, v] of this.store) {
			if (v.orderId.value === _id) {
				this.store.delete(k)
			}
		}
	}

	seed(entity: OrderOverride): void {
		this.store.set(this.key(entity.orderId.value, entity.storeIntegrationExternalId), entity)
	}

	clear(): void {
		this.store.clear()
	}
}
